-- C1e (owner decision 2026-10-28 12:07, DECISIONS-STAGE-A §13, D-450).
-- §13.2 the size search reads each style by its size class: `box` (as stated), `bag` (width × gusset × height),
-- `cylinder` (diameter square × height) or `not_applicable` (labels, tags, sleeves, inserts, flat folders: no range,
-- out of the size search, not counted as missing). Set by the fit-range backfill from the documented rule
-- (`size-classes.ts`); every existing style starts as `box` (the C1c behaviour) until the backfill runs.
ALTER TABLE "style_bases" ADD COLUMN "size_class" TEXT NOT NULL DEFAULT 'box';
ALTER TABLE "style_bases"
  ADD CONSTRAINT ck_style_bases__size_class CHECK (size_class IN ('box', 'bag', 'cylinder', 'not_applicable'));

-- §13.3 the trust-section editor picks uploaded files: pictures (production photos, customer logos, material swatches)
-- must be uploaded images (`/v1/store/catalog/images/{fileId}`); documents are uploaded files
-- (`/v1/store/style-library/documents/{fileId}`) or an external https link. The definition's JSON Schema follows
-- `STYLE_LIBRARY_CONTENT_SCHEMA` (the seed only writes it for a new definition). Existing versions are not rewritten.
UPDATE "settings"
SET "value_schema" = '{"type":"object","additionalProperties":false,"required":["quickSearch","materialSwatches","trust"],"properties":{"quickSearch":{"type":"array","maxItems":12,"items":{"type":"object","additionalProperties":false,"required":["label","query"],"properties":{"label":{"type":"object","additionalProperties":false,"required":["th","en"],"properties":{"th":{"type":"string","minLength":1,"maxLength":500},"en":{"type":["string","null"],"minLength":1,"maxLength":500}}},"query":{"type":"string","minLength":1,"maxLength":120}}}},"materialSwatches":{"type":"array","maxItems":20,"items":{"type":"object","additionalProperties":false,"required":["materialClass","colour","imageUrl"],"properties":{"materialClass":{"type":"string","pattern":"^[a-z][a-z0-9_]*$","maxLength":40},"colour":{"type":["string","null"],"pattern":"^#[0-9A-Fa-f]{6}$"},"imageUrl":{"type":["string","null"],"pattern":"^/v1/store/catalog/images/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","maxLength":2000}}}},"trust":{"type":"object","additionalProperties":false,"required":["certifications","foodGrade","productionPhotos","customerLogos","taxInvoiceNote"],"properties":{"certifications":{"type":"array","maxItems":20,"items":{"type":"object","additionalProperties":false,"required":["title","number","issuer","expiresOn","documentUrl"],"properties":{"title":{"type":"object","additionalProperties":false,"required":["th","en"],"properties":{"th":{"type":"string","minLength":1,"maxLength":500},"en":{"type":["string","null"],"minLength":1,"maxLength":500}}},"number":{"type":["string","null"],"minLength":1,"maxLength":120},"issuer":{"type":["string","null"],"minLength":1,"maxLength":200},"expiresOn":{"type":["string","null"],"pattern":"^\\d{4}-\\d{2}-\\d{2}$"},"documentUrl":{"type":["string","null"],"pattern":"^(https://[^\\s]+|/v1/store/style-library/documents/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$","maxLength":2000}}}},"foodGrade":{"type":"array","maxItems":20,"items":{"type":"object","additionalProperties":false,"required":["title","documentUrl"],"properties":{"title":{"type":"object","additionalProperties":false,"required":["th","en"],"properties":{"th":{"type":"string","minLength":1,"maxLength":500},"en":{"type":["string","null"],"minLength":1,"maxLength":500}}},"documentUrl":{"type":["string","null"],"pattern":"^(https://[^\\s]+|/v1/store/style-library/documents/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$","maxLength":2000}}}},"productionPhotos":{"type":"array","maxItems":24,"items":{"type":"object","additionalProperties":false,"required":["url","alt"],"properties":{"url":{"type":"string","pattern":"^/v1/store/catalog/images/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","maxLength":2000},"alt":{"type":"object","additionalProperties":false,"required":["th","en"],"properties":{"th":{"type":"string","minLength":1,"maxLength":500},"en":{"type":["string","null"],"minLength":1,"maxLength":500}}}}}},"customerLogos":{"type":"array","maxItems":40,"items":{"type":"object","additionalProperties":false,"required":["name","logoUrl","permission"],"properties":{"name":{"type":"string","minLength":1,"maxLength":120},"logoUrl":{"type":"string","pattern":"^/v1/store/catalog/images/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","maxLength":2000},"permission":{"type":"string","minLength":1,"maxLength":300}}}},"taxInvoiceNote":{"oneOf":[{"type":"null"},{"type":"object","additionalProperties":false,"required":["th","en"],"properties":{"th":{"type":"string","minLength":1,"maxLength":500},"en":{"type":["string","null"],"minLength":1,"maxLength":500}}}]}}}}}'::jsonb,
    "updated_at" = now(),
    "row_version" = "row_version" + 1
WHERE "key" = 'storefront.style_library' AND "scope_type" = 'platform' AND "scope_id" IS NULL;
